  if (base::is.finite(timeout)) request <- httr2::req_timeout(request, timeout)
  if (retries > 0 && (base::toupper(method) %in% base::c('GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE') || writes)) {
    request <- httr2::req_retry(request, max_tries = retries + 1,
      is_transient = is_transient)
  }
  if (!base::is.null(throttle)) request <- httr2::req_throttle(request, capacity = throttle$capacity, fill_time_s = throttle$fill_time_s, realm = throttle$realm)
  if (verbose) base::message(base::toupper(method), if (dry) ' request (dry run)' else ' request')
  if (dry) base::return(request)
  request <- httr2::req_error(request, is_error = function(response) FALSE)
  response <- base::tryCatch(httr2::req_perform(request), error = function(e) {
    if (preserve_errors) base::stop(e)
    if (base::is.finite(timeout) && base::inherits(e$parent, 'curl_error_operation_timedout')) base::stop('HTTP request failed before a response was received: timeout of ', timeout, ' s reached (raise request_controls.timeout, or use Inf for no limit)', call. = FALSE)
    base::stop('HTTP request failed before a response was received (connection, TLS, or timeout failure)', call. = FALSE)
  })
  if (verbose) base::message('HTTP ', httr2::resp_status(response))
  .ct_request_decode(response, method, response_policy, policy_query, preserve_errors)
}

# Decode an already-received response without performing transport or changing hook execution.
.ct_request_decode <- function(response, method = 'GET', response_policy = NULL, policy_query = NULL, preserve_errors = FALSE) {
  if (!base::is.logical(preserve_errors) || base::length(preserve_errors) != 1L || base::is.na(preserve_errors)) base::stop(base::errorCondition('preserve_errors must be TRUE or FALSE', class = 'specmill_call_error', call = NULL))
  status <- httr2::resp_status(response)
  media <- httr2::resp_header(response, 'content-type')
  if (base::is.null(media)) media <- ''
  media <- base::tolower(base::trimws(base::sub(';.*$', '', media)))
  diagnostic <- base::paste0('HTTP ', status, if (base::nzchar(media)) base::paste0(' ', media) else '')
  # Captures the final response. Policy return values, including NULL, are results.
  decode <- function(format = 'native', check_status = TRUE, col_classes = NA) {
    format <- base::match.arg(format, base::c('native', 'delimited'))
    if (!base::is.logical(check_status) || base::length(check_status) != 1L || base::is.na(check_status)) base::stop('check_status must be TRUE or FALSE', call. = FALSE)
    if (check_status && status >= 400L) {
      if (preserve_errors && status != 401L) httr2::resp_check_status(response)
      # A rejected credential applies to every item of a batch, so it stops the call rather than being dropped per item.
      base::stop(if (status == 401L) base::errorCondition(base::paste0(diagnostic, ' response'), class = 'specmill_call_error', call = NULL) else base::simpleError(base::paste0(diagnostic, ' response')))
    }
    delimited <- format == 'delimited' && media %in% base::c('text/csv', 'application/csv', 'text/tab-separated-values', 'text/tsv')
    if (!httr2::resp_has_body(response) || !base::length(httr2::resp_body_raw(response))) {
      base::return(if (delimited) base::data.frame() else NULL)
    }
    if (delimited) {
      text <- httr2::resp_body_string(response)
      separator <- if (media %in% base::c('text/tab-separated-values', 'text/tsv')) '\t' else ','
      connection <- base::textConnection(text)
      base::on.exit(base::close(connection), add = TRUE)
      # read.table otherwise infers row names when every row has an extra field.
      counts <- base::withCallingHandlers(utils::count.fields(connection, sep = separator, quote = '"', comment.char = ''), warning = function(w) base::stop(base::conditionMessage(w), call. = FALSE))
      counts <- counts[!base::is.na(counts)]
      if (!base::length(counts)) base::return(base::data.frame())
      if (base::any(counts != counts[[1L]])) base::stop('Malformed delimited response: inconsistent field counts', call. = FALSE)
      base::return(base::withCallingHandlers(utils::read.table(text = text, header = TRUE, sep = separator, quote = '"', comment.char = '', check.names = FALSE, stringsAsFactors = FALSE, fill = FALSE, colClasses = col_classes), warning = function(w) base::stop(base::conditionMessage(w), call. = FALSE)))
    }
    if (base::grepl('(/json|\\+json)$', media)) {
      decoded <- base::tryCatch(jsonlite::fromJSON(httr2::resp_body_string(response), simplifyVector = FALSE), error = base::identity)
      if (base::inherits(decoded, 'error')) base::stop('Cannot decode ', diagnostic, ' response as JSON', call. = FALSE)
      base::return(decoded)
    }
    if (base::startsWith(media, 'text/') || media == 'image/svg+xml') base::return(httr2::resp_body_string(response))
    httr2::resp_body_raw(response)
  }
  if (base::is.null(response_policy)) base::return(decode())
  response_policy(response, base::c(base::list(method = base::toupper(method), status = status, media = media), if (!base::is.null(policy_query)) base::list(query = policy_query)), decode)
}

# Select once in service defaults; actual response media chooses the delimiter.
.ct_request_delimited <- function(response, context, decode) decode(format = 'delimited')

# Explicit collection formatting, suitable for an existing post_response hook.
.ct_request_records <- function(result, collection = base::character(), query = NULL, null_to_na = FALSE, keyed = FALSE) {
  if (!base::is.character(collection) || base::anyNA(collection)) base::stop('collection must be a character path')
  for (field in collection) {
    if (!base::is.list(result) || !field %in% base::names(result)) base::stop('Missing collection field: ', field)
    result <- result[[field]]
  }
  records <- if (base::is.null(result) || !base::length(result)) base::list() else if (base::is.data.frame(result)) {
    base::lapply(base::seq_len(base::nrow(result)), function(i) base::as.list(result[i, , drop = FALSE]))
  } else if (base::is.list(result)) {
    if (!keyed && !base::is.null(base::names(result))) base::list(result) else result
  } else base::as.list(result)
  if (!base::is.null(query) && base::length(query) != 1L && base::length(query) != base::length(records)) base::stop('query must have length one or match records')
  formatted <- base::lapply(base::seq_along(records), function(i) {
    record <- records[[i]]
    if (null_to_na && base::is.list(record)) record[base::vapply(record, base::is.null, base::logical(1))] <- NA
    if (!base::is.null(query) && !base::is.null(record)) base::attr(record, 'query') <- query[if (base::length(query) == 1L) 1L else i]
    record
  })
  stats::setNames(formatted, base::names(records))
}

# Selected compatibility table: collapse nested fields, then optionally recover types.
# Supply tibble::as_tibble as as_table only in a client that declares tibble in Imports.
.ct_request_table <- function(records, type_convert = TRUE, names_to = NULL, as_table = base::identity, build = NULL) {
  table <- .ct_request_build(records, type_convert, names_to, as_table, build)
  # Inside a batched wrapper keep the records: .ct_request_combine() builds the table once over every request's records, so column types are not guessed per request.
  if (.ct_request_batch_state$active) base::attr(table, '.ct_request_source') <- base::list(records = records, type_convert = type_convert, names_to = names_to, as_table = as_table, build = build)
  table
}

# Set while .ct_request_each() runs a request; saved and restored so batches can nest.
.ct_request_batch_state <- base::new.env(parent = base::emptyenv())
.ct_request_batch_state$active <- FALSE

# The table .ct_request_table() describes, without any batch bookkeeping. A client's own `build(records, type_convert, names_to)`
# replaces the built-in row construction and must return a data frame; it is called per request and again over all records when pages are combined.
.ct_request_build <- function(records, type_convert = TRUE, names_to = NULL, as_table = base::identity, build = NULL) {
  if (!base::is.list(records) || !base::is.function(as_table)) base::stop('Supply records as a list and as_table as a function')
  if (!base::is.null(build)) {
    if (!base::is.function(build)) base::stop('build must be NULL or a function')
    result <- build(records, type_convert, names_to)
    if (!base::is.data.frame(result)) base::stop('build must return a data frame')
    base::return(as_table(result))
  }
  rows <- base::lapply(base::seq_along(records), function(i) {
    record <- records[[i]]
    if (base::is.null(record) || !base::length(record)) base::return(NULL)
    query <- base::attr(record, 'query', exact = TRUE)
    if (!base::is.list(record)) record <- base::list(value = record)
    if (base::is.null(base::names(record)) || base::anyNA(base::names(record)) || base::anyDuplicated(base::names(record))) base::stop('Table records must have unique field names')
    row <- base::lapply(record, function(value) {
      if (base::is.null(value) || !base::length(value)) NA_character_
      else base::paste(base::as.character(base::unlist(value)), collapse = '; ')
    })
    if (!base::is.null(query)) {
      if ('query' %in% base::names(row)) base::stop('Query attribution would replace a record field')
      row$query <- base::as.character(query)
    }
    if (!base::is.null(names_to)) {
      if (!base::is.character(names_to) || base::length(names_to) != 1L || base::is.na(names_to) || !base::nzchar(names_to) || names_to %in% base::names(row)) base::stop('names_to must name a new column')
      row[[names_to]] <- if (base::is.null(base::names(records))) base::as.character(i) else base::names(records)[[i]]
    }
    row
  })
  rows <- base::Filter(base::Negate(base::is.null), rows)
  if (!base::length(rows)) base::return(as_table(base::data.frame()))
  fields <- base::unique(base::unlist(base::lapply(rows, base::names), use.names = FALSE))
  columns <- base::lapply(fields, function(field) {
    values <- base::vapply(rows, function(row) if (base::is.null(row[[field]])) NA_character_ else row[[field]], base::character(1))
    if (type_convert) utils::type.convert(values, as.is = TRUE) else values
  })
  result <- base::structure(stats::setNames(columns, fields), class = 'data.frame', row.names = base::seq_along(rows))
  as_table(result)
}

# Sends one request per item or chunk for batch.fan_out and batch.split wrappers.
# The <helper>.batching option's on_error, empty and max_items override the generated defaults.
# on_error = 'drop' covers per-item failures only; errors classed specmill_call_error stop the call.
# When drop leaves no successes, `empty()` (the batch.empty client function) supplies the result instead of list().
.ct_request_each <- function(send, items, size, on_error = 'stop', empty = NULL, warning = NULL) {
  policy <- base::getOption(base::paste0(base::tolower(base::sub('_DRY_RUN$', '', "COMPTOXR_NATIVE_DRY_RUN")), '.ct_request.batching'), base::list())
  if (!base::is.null(policy$on_error)) on_error <- policy$on_error
  if (!base::is.null(policy$empty)) empty <- policy$empty
  # max_items lowers a split wrapper's chunk size; the generated max_items is the cap. Fan-out (size 1) is unaffected.
  if (!base::is.null(policy$max_items) && size > 1L) {
    limit <- policy$max_items
    if (!base::is.numeric(limit) || base::length(limit) != 1L || base::is.na(limit) || limit < 1 || limit != base::floor(limit) || limit > size) base::stop('batching max_items must be a whole number from 1 to ', size, call. = FALSE)
    size <- limit
  }
  if (base::is.list(on_error)) {
    if (base::length(on_error) != 2L || !base::setequal(base::names(on_error), base::c('single', 'multiple')) || !base::all(base::vapply(on_error, function(choice) base::identical(choice, 'stop') || base::identical(choice, 'drop'), base::logical(1)))) base::stop('on_error requires single and multiple stop/drop choices', call. = FALSE)
  } else if (!base::identical(on_error, 'stop') && !base::identical(on_error, 'drop')) base::stop('on_error must be stop or drop for fan_out and split wrappers', call. = FALSE)
  # Input within one request (including empty or NULL) is sent unchanged, as an unbatched call would.
  chunks <- if (base::length(items) > size) base::unname(base::split(items, base::ceiling(base::seq_along(items) / size))) else base::list(items)
  if (base::is.list(on_error)) on_error <- on_error[[if (base::length(chunks) == 1L) 'single' else 'multiple']]
  if (!base::is.null(warning) && !base::isFALSE(warning) && !base::is.function(warning)) base::stop(base::errorCondition('batch.warning must be a function or FALSE', class = 'specmill_call_error', call = NULL))
  failed <- base::character()
  run <- function(chunk) {
    outer <- .ct_request_batch_state$active
    .ct_request_batch_state$active <- TRUE
    base::on.exit(.ct_request_batch_state$active <- outer, add = TRUE)
    send(chunk)
  }
  results <- base::lapply(chunks, function(chunk) {
    if (on_error == 'stop') base::return(run(chunk))
    base::tryCatch(run(chunk), error = function(e) {
      # Call-level errors (credentials, server, options) apply to every item: stop rather than drop.
      if (base::inherits(e, 'specmill_call_error')) base::stop(e)
      label <- base::paste(base::as.character(base::unlist(chunk)), collapse = ', ')
      message <- if (base::is.null(warning)) base::paste0('Request for ', label, ' failed: ', base::conditionMessage(e)) else if (base::isFALSE(warning)) NULL else base::tryCatch(warning(e, chunk), error = function(error) {
        base::class(error) <- base::unique(base::c('specmill_call_error', base::class(error)))
        base::stop(error)
      })
      if (!base::is.null(message)) {
        if (!base::is.character(message) || base::length(message) != 1L || base::is.na(message) || !base::nzchar(message)) base::stop(base::errorCondition('batch.warning must return one nonempty string or NULL', class = 'specmill_call_error', call = NULL))
        base::warning(message, call. = FALSE)
      }
      failed[[label]] <<- base::conditionMessage(e)
      NULL
    })
  })
  result <- if (!base::is.null(empty) && base::length(failed) && base::all(base::vapply(results, base::is.null, base::logical(1)))) empty() else .ct_request_combine(results)
  if (base::length(failed)) base::attr(result, 'failed') <- failed
  result
}

# Runs one request per page for a wrapper with page or cursor pagination. `send` takes the page argument as a named
# list and returns that page's result; <helper>_paginated() decides when to stop. The pages are combined like a
# batched wrapper's, so tables are typed once. Every control the pagination option could change is fixed here,
# so the shape of a wrapper's result never depends on it. A dry run returns its first prepared request.
.ct_request_pages <- function(send, parameter, start, max_pages, completed = NULL, mode = 'page', next_cursor = NULL, items = NULL, error_policy = 'stop', warn_limits = TRUE, warn_errors = TRUE, stop_on_empty = TRUE, on_limit = NULL, size_parameter = NULL, page_size = NULL, advance = NULL) {
  for (callback in base::list(completed, next_cursor, items, on_limit, advance)) if (!base::is.null(callback) && !base::is.function(callback)) base::stop('Pagination callbacks must be functions', call. = FALSE)
  pages <- base::list()
  prepared <- NULL
  fetch <- function(...) {
    outer <- .ct_request_batch_state$active
    .ct_request_batch_state$active <- TRUE
    base::on.exit(.ct_request_batch_state$active <- outer, add = TRUE)
    page <- send(base::lapply(base::list(...), function(x) if (base::is.numeric(x) && base::length(x) == 1L && !base::is.na(x) && x == base::trunc(x) && base::abs(x) <= base::.Machine$integer.max) base::as.integer(x) else x))
    if (base::inherits(page, 'httr2_request')) {
      prepared <<- page
      return(base::list(response = NULL, items = base::list()))
    }
    selected <- if (base::is.null(items)) page else base::tryCatch(items(page), error = function(e) { base::class(e) <- base::unique(base::c('pagination_security_error', base::class(e))); base::stop(e) })
    pages[base::length(pages) + 1L] <<- base::list(selected)
    base::list(response = page, items = selected)
  }
  paginate <- base::get0('.ct_request_paginated', mode = 'function')
  if (base::is.null(paginate)) base::stop('Paging needs the pagination companion (.ct_request_paginated) in the client helper', call. = FALSE)
  paged <- paginate(fetch, mode = mode, parameter = parameter, start = start, size_parameter = size_parameter, page_size = page_size, items = function(x) if (base::is.null(x$items)) base::list() else x$items, completed = function(x, state) if (!base::is.null(prepared)) TRUE else if (base::is.null(completed)) FALSE else completed(x$response, state), next_cursor = if (base::is.null(next_cursor)) NULL else function(x) next_cursor(x$response), max_pages = max_pages, max_items = NULL, advance = if (base::is.null(advance)) NULL else function(x, position, page_size) advance(x$response, position, page_size), format = NULL, stop_on_short = FALSE, error_policy = error_policy, warn_limits = warn_limits && base::is.null(on_limit), warn_errors = warn_errors, stop_on_empty = stop_on_empty, policy = base::list())
  if (!base::is.null(prepared)) base::return(prepared)
  if (paged$stop_reason == 'request_error' && error_policy == 'empty') pages <- base::list()
  if (warn_limits && !base::is.null(on_limit) && base::length(pages) >= max_pages) on_limit(paged, max_pages)
  result <- .ct_request_combine(pages)
  base::attr(result, 'pagination') <- base::list(requests = base::as.integer(paged$requests), item_count = base::as.integer(paged$item_count), stop_reason = paged$stop_reason)
  result
}

# Tables built by .ct_request_table() are rebuilt once over all requests' records, so types are guessed
# on the whole result (as_table functions that differ only in their environment count as the same). Otherwise data frames are stacked (missing columns become NA), or the result is one list of records.
.ct_request_combine <- function(results) {
  results <- base::Filter(base::Negate(base::is.null), results)
  # Attributes a policy attached to a page (for example the paging fields a completion rule reads) are not edits to its data.
  plain <- function(x) {
    for (name in base::setdiff(base::names(base::attributes(x)), base::c('names', 'row.names', 'class'))) base::attr(x, name) <- NULL
    x
  }
  # One result has nothing to combine, and like any combined result it carries no per-page attributes; inside an outer batch it keeps them, with its records, for that batch.
  if (base::length(results) == 1L && base::is.data.frame(results[[1L]])) {
    base::return(if (.ct_request_batch_state$active) results[[1L]] else plain(results[[1L]]))
  }
  sources <- base::lapply(results, function(x) if (base::is.data.frame(x)) base::attr(x, '.ct_request_source', exact = TRUE))
  results <- base::lapply(results, function(x) {
    if (base::is.data.frame(x)) base::attr(x, '.ct_request_source') <- NULL
    x
  })
  if (base::length(results) && base::all(base::vapply(results, base::is.data.frame, base::logical(1)))) {
    table_args <- base::lapply(sources, function(x) x[base::c('type_convert', 'names_to', 'as_table', 'build')])
    # Rebuild only when every table is exactly what .ct_request_table() would return for its own records with the
    # first request's options (no hook edited it, the options agree), and record names are consistent when they are used.
    named <- base::vapply(sources, function(x) if (base::length(x$records)) !base::is.null(base::names(x$records)) else NA, base::logical(1))
    unchanged <- !base::any(base::vapply(sources, base::is.null, base::logical(1))) &&
      base::all(base::vapply(table_args, base::identical, base::logical(1), table_args[[1L]], ignore.environment = TRUE)) &&
      (base::is.null(table_args[[1L]]$names_to) || base::length(base::unique(named[!base::is.na(named)])) <= 1L) &&
      base::all(base::vapply(base::seq_along(results), function(i) base::tryCatch(base::identical(plain(results[[i]]), plain(base::do.call(.ct_request_build, base::c(base::list(records = sources[[i]]$records), table_args[[1L]])))), error = function(e) FALSE), base::logical(1)))
    if (unchanged) base::return(base::do.call(.ct_request_table, base::c(base::list(records = base::do.call(base::c, base::unname(base::lapply(sources, function(x) x$records)))), table_args[[1L]])))
    columns <- base::unique(base::unlist(base::lapply(results, base::names), use.names = FALSE))
    results <- base::lapply(results, function(x) {
      for (column in base::setdiff(columns, base::names(x))) x[[column]] <- base::rep(NA, base::nrow(x))
      x[columns]
    })
    base::return(base::do.call(base::rbind, base::unname(results)))
  }
  records <- base::lapply(results, function(x) if (base::is.list(x) && !base::is.data.frame(x) && base::is.null(base::names(x))) x else base::list(x))
  base::do.call(base::c, base::c(base::list(base::list()), base::unname(records)))
}

#' Client-owned batched companion
#' @param fn Client-owned single-request function to call.
#' @param items Batch inputs, or an explicit response collection extractor for pagination.
#' @param size Positive integer maximum batch length.
#' @param ... Fixed arguments passed unchanged to the single-request function.
#' @param policy Named list of explicit shared client choices; individual pagination arguments override it.
#' @export
.ct_request_batched <- function(fn, items, size, ..., policy = base::getOption(base::paste0(base::tolower(base::sub("_DRY_RUN$", 
    "", "COMPTOXR_NATIVE_DRY_RUN")), ".ct_request.batching"), base::list())) {
    if (!base::is.numeric(size) || base::length(size) != 1L || base::is.na(size) || 
        !base::is.finite(size) || size < 1 || size != base::floor(size)) {
        base::stop("size must be a positive integer")
    }
    if (!base::is.function(fn)) {
        base::stop("fn must be a function")
    }
    allowed <- base::c("normalize", "build", "merge", "on_error", "error_result", 
        "first_batch_only")
    if (!base::is.list(policy) || (base::length(policy) && (base::is.null(base::names(policy)) || 
        base::anyNA(base::names(policy)) || base::anyDuplicated(base::names(policy)))) || 
        base::length(base::setdiff(base::names(policy), allowed))) {
        base::stop("policy must be a named list of normalize, build, merge, on_error, error_result, first_batch_only")
    }
    for (name in base::c("normalize", "build", "merge")) {
        if (!base::is.null(policy[[name]]) && !base::is.function(policy[[name]])) {
            base::stop(name, " must be a function")
        }
    }
    on_error <- if (base::is.null(policy$on_error)) 
        "stop"
    else policy$on_error
    if (base::length(on_error) != 1L || base::is.na(on_error) || !on_error %in% base::c("stop", 
        "drop", "keep")) {
        base::stop("on_error must be stop, drop, or keep")
    }
    if (!base::is.null(policy$first_batch_only) && !base::identical(policy$first_batch_only, 
        TRUE) && !base::identical(policy$first_batch_only, FALSE)) {
        base::stop("first_batch_only must be TRUE or FALSE")
    }
    if (!base::is.null(policy$normalize)) {
        items <- policy$normalize(items)
    }
    chunks <- base::split(items, base::ceiling(base::seq_along(items)/size))
    if (base::isTRUE(policy$first_batch_only) && base::length(chunks)) {
        chunks <- chunks[1L]
    }
    results <- base::list()
    for (index in base::seq_along(chunks)) {
        chunk <- chunks[[index]]
        if (!base::is.null(policy$build)) {
            chunk <- policy$build(chunk, index)
        }
        result <- if (on_error == "stop") {
            base::list(value = fn(chunk, ...), failed = FALSE)
        }
        else {
            base::tryCatch(base::list(value = fn(chunk, ...), failed = FALSE), error = function(error) {
                base::warning("Batch ", index, " failed: ", base::conditionMessage(error), 
                  call. = FALSE)
                base::list(value = policy$error_result, failed = TRUE)
            })
        }
        if (!result$failed || on_error == "keep") {
            results[base::names(chunks)[index]] <- base::list(result$value)
        }
    }
    if (base::is.null(policy$merge)) 
        results
    else policy$merge(results)
}

#' Client-owned paginated companion
#' @param fn Client-owned single-request function to call.
#' @param ... Fixed arguments passed unchanged to the single-request function.
#' @param mode Explicit page, offset, or cursor strategy.
#' @param parameter Exact public argument name or nested character-vector argument path.
#' @param size_parameter Exact argument name or nested path for the page size.
#' @param page_size Positive integer requested page size.
#' @param start Initial page/offset integer, or initial opaque cursor string or NULL.
#' @param items Batch inputs, or an explicit response collection extractor for pagination.
#' @param max_pages Positive integer call bound, default 100.
#' @param max_items Optional positive integer retained-item bound; NULL means no item cap.
#' @param next_cursor Function extracting an opaque next cursor string or NULL.
#' @param completed Optional function of response and state selecting metadata completion.
#' @param advance Optional function of response, position and page_size returning the next position.
#' @param stop_on_short Whether a short page signals completion, default FALSE.
#' @param error_policy Request error policy: stop by default, or explicit partial/empty recovery with warnings.
#' @param warn_limits Whether truncation warns, default TRUE in emitted companions.
#' @param format Optional final-result formatter, applied after iteration consumes metadata.
#' @param policy Named list of explicit shared client choices; individual pagination arguments override it.
#' @param warn_errors NA
#' @param stop_on_empty NA
#' @export
.ct_request_paginated <- function(fn, ..., mode, parameter, size_parameter = NULL, 
    page_size = NULL, start = NULL, items, max_pages = 100, max_items = NULL, next_cursor = NULL, 
    completed = NULL, advance = NULL, stop_on_short = FALSE, error_policy = "stop", 
    warn_limits = TRUE, format = NULL, policy = base::getOption(base::paste0(base::tolower(base::sub("_DRY_RUN$", 
        "", "COMPTOXR_NATIVE_DRY_RUN")), ".ct_request.pagination"), base::list()), warn_errors = TRUE, 
    stop_on_empty = TRUE) {
    allowed <- base::setdiff(base::names(base::formals(base::sys.function())), base::c("fn", 
        "...", "policy"))
    if (!base::is.list(policy) || (base::length(policy) && (base::is.null(base::names(policy)) || 
        base::anyNA(base::names(policy)) || !base::all(base::nzchar(base::names(policy))) || 
        base::anyDuplicated(base::names(policy)) || !base::all(base::names(policy) %in% 
        allowed)))) {
        base::stop("policy must be a named list of pagination defaults")
    }
    supplied <- base::names(base::match.call(expand.dots = FALSE))
    for (name in base::setdiff(base::names(policy), supplied)) {
        base::assign(name, policy[[name]])
    }
    for (value in base::list(completed, advance, format)) {
        if (!base::is.null(value) && !base::is.function(value)) {
            base::stop("Pagination callbacks must be functions")
        }
    }
    for (value in base::list(stop_on_short, warn_limits, warn_errors, stop_on_empty)) {
        if (!base::is.logical(value) || base::length(value) != 1L || base::is.na(value)) {
            base::stop("Pagination flags must be logical")
        }
    }
    if (!base::is.character(error_policy) || base::length(error_policy) != 1L || 
        base::is.na(error_policy) || !error_policy %in% base::c("stop", "partial", 
        "empty")) {
        base::stop("error_policy must be stop, partial, or empty")
    }
    if (!base::is.function(fn) || !base::is.function(items)) {
        base::stop("fn and items must be functions")
    }
    if (!base::is.character(mode) || base::length(mode) != 1L || base::is.na(mode) || 
        !mode %in% base::c("page", "offset", "cursor")) {
        base::stop("mode must be page, offset, or cursor")
    }
    cursor <- mode == "cursor"
    if (cursor) {
        if (!base::is.function(next_cursor)) {
            base::stop("cursor mode requires next_cursor")
        }
        .ct_request_pagination_token(start)
        if (base::is.null(size_parameter) != base::is.null(page_size)) {
            base::stop("Supply size_parameter and page_size together")
        }
    }
    else if (base::is.null(start)) {
        base::stop("page/offset mode requires start")
    }
    else if (mode == "offset" && (base::is.null(size_parameter) || base::is.null(page_size))) {
        base::stop("offset mode requires size_parameter and page_size")
    }
    else if (base::is.null(size_parameter) != base::is.null(page_size)) {
        base::stop("Supply size_parameter and page_size together")
    }
    for (name in base::c(base::list(parameter), if (!base::is.null(size_parameter)) 
        base::list(size_parameter))) {
        if (!base::is.character(name) || !base::length(name) || base::anyNA(name) || 
            !base::all(base::nzchar(name))) {
            base::stop("pagination argument path must contain nonempty names")
        }
        if (!name[[1L]] %in% base::names(base::formals(fn)) && !"..." %in% base::names(base::formals(fn))) {
            base::stop("Unknown pagination argument: ", name)
        }
    }
    overlaps <- function(x, y) {
        !base::is.null(y) && base::identical(x[base::seq_len(base::min(base::length(x), 
            base::length(y)))], y[base::seq_len(base::min(base::length(x), base::length(y)))])
    }
    if (overlaps(parameter, size_parameter)) {
        base::stop("Pagination arguments must be distinct")
    }
    numbers <- base::list(page_size = page_size, start = start, max_pages = max_pages, 
        max_items = max_items)
    if (base::is.null(max_items)) {
        numbers$max_items <- NULL
    }
    if (cursor) {
        numbers$start <- NULL
    }
    if (base::is.null(page_size)) {
        numbers$page_size <- NULL
    }
    for (name in base::names(numbers)) {
        value <- numbers[[name]]
        if (!base::is.numeric(value) || base::length(value) != 1L || base::is.na(value) || 
            !base::is.finite(value) || value != base::floor(value) || value < (if (name == 
            "start") 
            0
        else 1) || value > 2^53 - 1) {
            base::stop(name, " must be a finite integer within the supported range")
        }
    }
    step <- if (mode == "page") 
        1
    else page_size
    if (!cursor && max_pages - 1 > (2^53 - 1 - start)/step) {
        base::stop("Pagination positions exceed the exact integer range")
    }
    args <- base::list(...)
    if (base::length(args) && (base::is.null(base::names(args)) || base::anyNA(base::names(args)) || 
        !base::all(base::nzchar(base::names(args))) || base::anyDuplicated(base::names(args)) || 
        base::any(base::names(args) %in% base::c(if (base::length(parameter) == 1L) 
            parameter, if (base::length(size_parameter) == 1L) 
            size_parameter)))) {
        base::stop("Fixed arguments must have unique names and exclude pagination arguments")
    }
    set_path <- function(x, path, value) {
        if (base::is.null(x)) {
            x <- base::list()
        }
        if (!base::is.list(x)) {
            base::stop("Nested pagination state must be a list")
        }
        key <- path[[1L]]
        if (base::length(path) == 1L) {
            x[key] <- base::list(value)
        }
        else {
            x[key] <- base::list(set_path(x[[key]], path[-1L], value))
        }
        x
    }
    args <- set_path(args, parameter, start)
    if (!base::is.null(size_parameter)) {
        args <- set_path(args, size_parameter, page_size)
    }
    item_limit <- if (base::is.null(max_items)) 
        Inf
    else max_items
    pages <- base::list()
    count <- 0
    requests <- 0
    position <- start
    seen <- base::new.env(hash = TRUE, parent = base::emptyenv())
    if (cursor && !base::is.null(start) && base::nzchar(start)) {
        seen[[digest::digest(start, algo = "sha256")]] <- TRUE
    }
    repeat {
        args <- set_path(args, parameter, position)
        if (!base::is.null(size_parameter)) {
            args <- set_path(args, size_parameter, page_size)
        }
        requests <- requests + 1
        response <- base::tryCatch(base::do.call(fn, args), error = function(e) {
            if (error_policy == "stop" || base::inherits(e, base::c("pagination_security_error", 
                "specmill_call_error"))) {
                base::stop(e)
            }
            e
        })
        if (base::inherits(response, "error")) {
            if (warn_errors) {
                base::warning("Pagination request failed; returning ", error_policy, 
                  " results", call. = FALSE)
            }
            if (error_policy == "empty") {
                pages <- base::list()
                count <- 0
            }
            reason <- "request_error"
            break
        }
        page <- items(response)
        if (base::is.null(page) || !(base::is.data.frame(page) || (base::is.null(base::dim(page)) && 
            (base::is.list(page) || base::is.atomic(page))))) {
            base::stop("items must return a list, atomic vector, or data frame")
        }
        n <- if (base::is.data.frame(page)) 
            base::nrow(page)
        else base::length(page)
        if (!n && stop_on_empty) {
            reason <- "empty_page"
            break
        }
        keep <- base::min(n, item_limit - count)
        pages[[base::length(pages) + 1L]] <- if (base::is.data.frame(page)) {
            page[base::seq_len(keep), , drop = FALSE]
        }
        else {
            page[base::seq_len(keep)]
        }
        count <- count + keep
        if (count == item_limit) {
            reason <- "max_items"
            if (warn_limits) {
                base::warning("Pagination truncated at ", reason, call. = FALSE)
            }
            break
        }
        if (!base::is.null(completed)) {
            done <- completed(response, base::list(position = position, requests = requests, 
                item_count = count, page_size = page_size))
            if (!base::is.logical(done) || base::length(done) != 1L || base::is.na(done)) {
                base::stop("completed must return one nonmissing logical value")
            }
            if (done) {
                reason <- "completed"
                break
            }
        }
        if (stop_on_short && !base::is.null(page_size) && n < page_size) {
            reason <- "short_page"
            break
        }
        if (requests == max_pages) {
            reason <- "max_pages"
            if (warn_limits) {
                base::warning("Pagination truncated at ", reason, call. = FALSE)
            }
            break
        }
        if (cursor) {
            position <- next_cursor(response)
            .ct_request_pagination_token(position)
            if (base::is.null(position) || !base::nzchar(position)) {
                reason <- "no_next_cursor"
                break
            }
            key <- digest::digest(position, algo = "sha256")
            if (base::exists(key, envir = seen, inherits = FALSE)) {
                base::stop("Repeated pagination cursor or link")
            }
            seen[[key]] <- TRUE
        }
        else {
            next_position <- if (base::is.null(advance)) {
                position + step
            }
            else {
                advance(response, position, page_size)
            }
            if (!base::is.numeric(next_position) || base::length(next_position) != 
                1L || base::is.na(next_position) || !base::is.finite(next_position) || 
                next_position != base::floor(next_position) || next_position <= position || 
                next_position > 2^53 - 1) {
                base::stop("advance must return a larger exact integer position")
            }
            position <- next_position
        }
    }
    result <- base::list(pages = pages, requests = requests, item_count = count, 
        stop_reason = reason)
    if (base::is.null(format)) 
        result
    else format(result)
}

.ct_request_pagination_token <- function(value) {
    if (!base::is.null(value) && (!base::is.character(value) || base::length(value) != 
        1L || base::is.na(value))) {
        base::stop("Pagination cursor or link must be NULL or a single non-missing string")
    }
    base::invisible(value)
}

#' Client-owned paginated_links companion
#' @param request A bodyless httr2 GET request with authentication and transport policy configured.
#' @param items Batch inputs, or an explicit response collection extractor for pagination.
#' @param next_link Explicit next-link extractor; defaults to the HTTP Link header.
#' @param max_pages Positive integer call bound, default 100.
#' @param max_items Optional positive integer retained-item bound; NULL means no item cap.
#' @param warn_limits Whether truncation warns, default TRUE in emitted companions.
#' @param error_policy Request error policy: stop by default, or explicit partial/empty recovery with warnings.
#' @param format Optional final-result formatter, applied after iteration consumes metadata.
#' @param policy Named list of explicit shared client choices; individual pagination arguments override it.
#' @export
.ct_request_paginated_links <- function(request, items, next_link = function(response) httr2::resp_link_url(response, 
    "next"), max_pages = 100, max_items = NULL, warn_limits = TRUE, error_policy = "stop", 
    format = NULL, policy = base::getOption(base::paste0(base::tolower(base::sub("_DRY_RUN$", 
        "", "COMPTOXR_NATIVE_DRY_RUN")), ".ct_request.pagination_links"), base::list())) {
    if (base::missing(format) && base::is.list(policy)) {
        format <- policy$format
    }
    if (!base::is.null(format) && !base::is.function(format)) {
        base::stop("format must be a function")
    }
    if (!base::requireNamespace("httr2", quietly = TRUE) || utils::packageVersion("httr2") < 
        "1.3.0") {
        base::stop("paginated_links requires httr2 >= 1.3.0")
    }
    if (!base::inherits(request, "httr2_request") || !base::is.function(next_link)) {
        base::stop("Supply an httr2 request and a next_link function")
    }
    if ((!base::is.null(request$method) && request$method != "GET") || !base::is.null(request$body)) {
        base::stop("Next-link pagination requires a bodyless GET request")
    }
    parse_url <- function(url, base_url = NULL) {
        .ct_request_pagination_token(url)
        if (base::is.null(url) || !base::nzchar(url) || base::grepl("[[:space:]\\\\]", 
            url)) {
            base::stop("Invalid pagination URL")
        }
        parsed <- base::tryCatch(httr2::url_parse(url, base_url), error = function(e) {
            base::stop("Invalid pagination URL", call. = FALSE)
        })
        if (!parsed$scheme %in% base::c("http", "https") || base::is.null(parsed$hostname) || 
            !base::nzchar(parsed$hostname) || !base::is.null(parsed$username) || 
            !base::is.null(parsed$password) || !base::is.null(parsed$fragment)) {
            base::stop("Pagination URL must be HTTP(S) without userinfo or a fragment")
        }
        parsed
    }
    origin <- function(parsed) {
        base::list(base::tolower(parsed$scheme), base::tolower(parsed$hostname), 
            base::as.character(if (!base::is.null(parsed$port)) {
                parsed$port
            }
            else if (parsed$scheme == "https") {
                443
            }
            else {
                80
            }))
    }
    initial <- parse_url(httr2::req_get_url(request))
    trusted <- origin(initial)
    checked_url <- function(url, base_url = NULL) {
        parsed <- parse_url(url, base_url)
        if (!base::identical(origin(parsed), trusted)) {
            base::stop("Cross-origin pagination link refused")
        }
        parsed$scheme <- base::tolower(parsed$scheme)
        parsed$hostname <- base::tolower(parsed$hostname)
        if (base::identical(base::as.character(parsed$port), if (parsed$scheme == 
            "https") 
            "443"
        else "80")) {
            parsed$port <- NULL
        }
        httr2::url_build(parsed)
    }
    security_abort <- function(message) {
        base::stop(base::structure(base::list(message = message, call = NULL), class = base::c("pagination_security_error", 
            "error", "condition")))
    }
    fetch <- function(url) {
        req <- httr2::req_url(request, checked_url(url))
        req <- httr2::req_options(req, followlocation = FALSE)
        response <- httr2::req_perform(req)
        if (httr2::resp_status(response) >= 300 && httr2::resp_status(response) < 
            400) {
            security_abort("Pagination redirect refused")
        }
        httr2::resp_check_status(response)
        response
    }
    iteration <- base::list(fn = fetch, mode = "cursor", parameter = "url", start = checked_url(httr2::req_get_url(request)), 
        items = items, next_cursor = function(response) {
            link <- next_link(response)
            .ct_request_pagination_token(link)
            if (base::is.null(link) || !base::nzchar(link)) {
                return(NULL)
            }
            checked_url(link, httr2::resp_url(response))
        }, policy = policy)
    for (name in base::c("max_pages", "max_items", "warn_limits", "error_policy")) {
        if (!name %in% base::names(policy) || name %in% base::names(base::match.call())) {
            iteration[name] <- base::list(base::get(name))
        }
    }
    iteration["format"] <- base::list(NULL)
    result <- base::do.call(.ct_request_paginated, iteration)
    if (result$stop_reason == "no_next_cursor") {
        result$stop_reason <- "no_next_link"
    }
    if (base::is.null(format)) 
        result
    else format(result)
}
